insert into public.kanjis (id, character, han_viet, meanings, onyomi, kunyomi, stroke_count, jlpt_level, examples) values ('降', '降', '', '["descend","precipitate","fall","surrender"]'::jsonb, '["コウ","ゴ"]'::jsonb, '["お.りる","お.ろす","ふ.る","ふ.り","くだ.る","くだ.す"]'::jsonb, 10, 'N3', '[{"vocabularyId":204,"word":"降る","hiragana":"ふる","meaning":"rơi (mưa, tuyết)"}]'::jsonb) on conflict (id) do update set character = excluded.character, han_viet = excluded.han_viet, meanings = excluded.meanings, onyomi = excluded.onyomi, kunyomi = excluded.kunyomi, stroke_count = excluded.stroke_count, jlpt_level = excluded.jlpt_level, examples = excluded.examples;
insert into public.kanjis (id, character, han_viet, meanings, onyomi, kunyomi, stroke_count, jlpt_level, examples) values ('練', '練', '', '["practice","gloss","train","drill","polish","refine"]'::jsonb, '["レン"]'::jsonb, '["ね.る","ね.り"]'::jsonb, 14, 'N2', '[{"vocabularyId":206,"word":"練習する","hiragana":"れんしゅうする","meaning":"luyện tập"}]'::jsonb) on conflict (id) do update set character = excluded.character, han_viet = excluded.han_viet, meanings = excluded.meanings, onyomi = excluded.onyomi, kunyomi = excluded.kunyomi, stroke_count = excluded.stroke_count, jlpt_level = excluded.jlpt_level, examples = excluded.examples;
insert into public.kanjis (id, character, han_viet, meanings, onyomi, kunyomi, stroke_count, jlpt_level, examples) values ('習', '習', '', '["learn"]'::jsonb, '["シュウ","ジュ"]'::jsonb, '["なら.う","なら.い"]'::jsonb, 11, 'N4', '[{"vocabularyId":206,"word":"練習する","hiragana":"れんしゅうする","meaning":"luyện tập"}]'::jsonb) on conflict (id) do update set character = excluded.character, han_viet = excluded.han_viet, meanings = excluded.meanings, onyomi = excluded.onyomi, kunyomi = excluded.kunyomi, stroke_count = excluded.stroke_count, jlpt_level = excluded.jlpt_level, examples = excluded.examples;
insert into public.kanjis (id, character, han_viet, meanings, onyomi, kunyomi, stroke_count, jlpt_level, examples) values ('予', '予', '', '["beforehand","previous","myself","I"]'::jsonb, '["ヨ","シャ"]'::jsonb, '["あらかじ.め"]'::jsonb, 4, 'N3', '[{"vocabularyId":208,"word":"予約する","hiragana":"よやくする","meaning":"đặt trước"}]'::jsonb) on conflict (id) do update set character = excluded.character, han_viet = excluded.han_viet, meanings = excluded.meanings, onyomi = excluded.onyomi, kunyomi = excluded.kunyomi, stroke_count = excluded.stroke_count, jlpt_level = excluded.jlpt_level, examples = excluded.examples;
insert into public.kanjis (id, character, han_viet, meanings, onyomi, kunyomi, stroke_count, jlpt_level, examples) values ('泊', '泊', '', '["overnight stay","put up at","ride at anchor"]'::jsonb, '["ハク"]'::jsonb, '["と.まる","と.める"]'::jsonb, 8, 'N2', '[{"vocabularyId":209,"word":"泊まる","hiragana":"とまる","meaning":"trọ lại"}]'::jsonb) on conflict (id) do update set character = excluded.character, han_viet = excluded.han_viet, meanings = excluded.meanings, onyomi = excluded.onyomi, kunyomi = excluded.kunyomi, stroke_count = excluded.stroke_count, jlpt_level = excluded.jlpt_level, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-UCHINI-01', 'SHINKANZEN_N3', 'L01', 'N3', '～うちに（状態）', 'Vている + うちに / Vない + うちに / Aい + うちに / Aな + な + うちに', 'Trong lúc (trạng thái chưa thay đổi) thì làm V...', 'Sử dụng khi muốn diễn tả ý: "Trong lúc trạng thái A vẫn chưa thay đổi, thì hãy tranh thủ làm việc B". Nếu để trạng thái A thay đổi thì sẽ khó hoặc không thể làm việc B được nữa.', 'Không dùng cho những việc xảy ra ngoài ý muốn ở vế B.', '[{"japanese":"忘れないうちに、予定をメモしてください。","hiragana":"わすれないうちに、よていをメモしてください。","vietnamese":"Hãy ghi lại kế hoạch trước khi quên."},{"japanese":"料理が熱いうちに、早く食べてください。","hiragana":"りょうりがあついうちに、はやくたべてください。","vietnamese":"Hãy ăn nhanh trong lúc thức ăn còn nóng."},{"japanese":"明るいうちに、家に帰りましょう。","hiragana":"あかるいうちに、いえにかえりましょう。","vietnamese":"Hãy về nhà trong lúc trời còn sáng."},{"japanese":"元気なうちに、いろいろな国へ旅行したいです。","hiragana":"げんきなうちに、いろいろなくにへりょこうしたいです。","vietnamese":"Tôi muốn đi du lịch nhiều nước trong lúc còn khỏe."},{"japanese":"若いうちに、たくさん本を読んだほうがいいです。","hiragana":"わかいうちに、たくさんほんをよんだほうがいいです。","vietnamese":"Nên đọc nhiều sách trong lúc còn trẻ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-UCHINI-02', 'SHINKANZEN_N3', 'L01', 'N3', '～うちに（変化）', 'Vる + うちに / Vている + うちに', 'Trong khi đang (làm V) thì có một sự thay đổi xảy ra...', 'Sử dụng khi muốn diễn tả ý: "Trong quá trình đang làm việc A, thì một sự thay đổi B diễn ra một cách tự nhiên (ngoài ý muốn)".', 'Vế B KHÔNG PHẢI là hành động có chủ ý của người nói.', '[{"japanese":"日本で生活しているうちに、日本語が上手になりました。","hiragana":"にほんでせいかつしているうちに、にほんごがじょうずになりました。","vietnamese":"Sống ở Nhật một thời gian thì tiếng Nhật đã giỏi lên lúc nào không hay."},{"japanese":"何度も練習しているうちに、自転車に乗れるようになりました。","hiragana":"なんどもれんしゅうしているうちに、じてんしゃにのれるようになりました。","vietnamese":"Trong lúc luyện tập nhiều lần thì tôi đã biết đi xe đạp."},{"japanese":"友達と話しているうちに、悩みが消えてしまいました。","hiragana":"ともだちとはなしているうちに、なやみがきえてしまいました。","vietnamese":"Trong lúc nói chuyện với bạn thì những muộn phiền đã biến mất."},{"japanese":"本を読んでいるうちに、だんだん眠くなりました。","hiragana":"ほんをよんでいるうちに、だんだんねむくなりました。","vietnamese":"Trong lúc đang đọc sách thì tôi dần thấy buồn ngủ."},{"japanese":"その音楽を聞いているうちに、昔のことを思い出しました。","hiragana":"そのおんがくをきいているうちに、むかしのことをおもいだしました。","vietnamese":"Trong khi đang nghe bản nhạc đó thì tôi nhớ lại chuyện ngày xưa."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-AIDA', 'SHINKANZEN_N3', 'L01', 'N3', '～間（ずっと）', 'Vている + 間 / N + の + 間', 'Trong suốt (khoảng thời gian) ...', 'Dùng khi muốn nói: "Trong suốt khoảng thời gian A diễn ra, thì trạng thái/hành động B cũng liên tục diễn ra theo".', 'Nếu vế B là một hành động xảy ra chớp nhoáng (không kéo dài) thì phải dùng ～間に, không được dùng ～間.', '[{"japanese":"夏休みの間、ずっとアルバイトをしていました。","hiragana":"なつやすみのあいだ、ずっとアルバイトをしていました。","vietnamese":"Trong suốt kỳ nghỉ hè, tôi liên tục làm thêm."},{"japanese":"日本にいる間、ずっと日本語を勉強していました。","hiragana":"にほんにいるあいだ、ずっとにほんごをべんきょうしていました。","vietnamese":"Trong suốt thời gian ở Nhật, tôi đã liên tục học tiếng Nhật."},{"japanese":"授業の間、ずっと静かにしていました。","hiragana":"じゅぎょうのあいだ、ずっとしずかにしていました。","vietnamese":"Trong suốt buổi học, tôi đã luôn giữ im lặng."},{"japanese":"旅行の間、ずっと写真を撮っていました。","hiragana":"りょこうのあいだ、ずっとしゃしんをとっていました。","vietnamese":"Trong suốt chuyến du lịch, tôi đã liên tục chụp ảnh."},{"japanese":"映画を見ている間、ずっと彼と手をつないでいました。","hiragana":"えいがをみているあいだ、ずっとかれとてをつないでいました。","vietnamese":"Trong suốt lúc xem phim, tôi đã luôn nắm tay anh ấy."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-AIDANI', 'SHINKANZEN_N3', 'L01', 'N3', '～間に（瞬間）', 'Vている + 間に / N + の + 間に', 'Trong lúc (một khoảnh khắc nào đó) ...', 'Dùng khi muốn nói: "Trong khoảng thời gian A đang diễn ra, thì hành động B chen ngang hoặc hoàn thành".', 'Chú ý phân biệt với ～間. (間: A kéo dài, B cũng kéo dài. 間に: A kéo dài, B chỉ là một điểm).', '[{"japanese":"私が寝ている間に、電話がありました。","hiragana":"わたしがねているあいだに、でんわがありました。","vietnamese":"Trong lúc tôi đang ngủ thì có điện thoại."},{"japanese":"日本にいる間に、富士山を見たいです。","hiragana":"にほんにいるあいだに、ふじさんをみたいです。","vietnamese":"Trong khoảng thời gian ở Nhật, tôi muốn được nhìn thấy núi Phú Sĩ."},{"japanese":"母が料理している間に、宿題をしました。","hiragana":"ははがりょうりしているあいだに、しゅくだいをしました。","vietnamese":"Trong lúc mẹ đang nấu ăn, tôi đã làm bài tập."},{"japanese":"夏休みの間に、京都へ行きました。","hiragana":"なつやすみのあいだに、きょうとへいきました。","vietnamese":"Trong khoảng thời gian nghỉ hè, tôi đã đi Kyoto."},{"japanese":"独身の間に、いろいろなことに挑戦したいです。","hiragana":"どくしんのあいだに、いろいろなことにちょうせんしたいです。","vietnamese":"Trong lúc còn độc thân, tôi muốn thử thách nhiều điều."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-TEKARA-DENAITO', 'SHINKANZEN_N3', 'L01', 'N3', '～てからでないと / ～てからでなければ', 'Vて + からでないと', 'Nếu chưa ... thì không thể ...', 'Dùng khi muốn nhấn mạnh thứ tự trước sau: "Hành động A bắt buộc phải được thực hiện trước, nếu không có A thì B không thể xảy ra hoặc không được phép xảy ra".', 'Thường dùng trong các quy định, cảnh báo, hoặc điều kiện tiên quyết.', '[{"japanese":"切符を買ってからでないと、電車に乗れません。","hiragana":"きっぷをかってからでないと、でんしゃにのれません。","vietnamese":"Nếu chưa mua vé thì không thể lên tàu."},{"japanese":"予約してからでないと、ホテルに泊まれません。","hiragana":"よやくしてからでないと、ホテルにとまれません。","vietnamese":"Nếu chưa đặt trước thì không thể ở khách sạn."},{"japanese":"申し込んでからでないと、参加できません。","hiragana":"もうしこんでからでないと、さんかできません。","vietnamese":"Nếu chưa đăng ký thì không thể tham gia."},{"japanese":"宿題をしてからでないと、ゲームをしてはいけません。","hiragana":"しゅくだいをしてからでないと、ゲームをしてはいけません。","vietnamese":"Nếu chưa làm xong bài tập thì không được chơi game."},{"japanese":"お金を払ってからでないと、商品を受け取れません。","hiragana":"おかねをはらってからでないと、しょうひんをうけとれません。","vietnamese":"Nếu chưa trả tiền thì không thể nhận hàng."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3-SKZ-L01-TOKORO', 'SHINKANZEN_N3', 'L01', 'N3', '～ところだ', 'Vる + ところ / Vている + ところ / Vた + ところ', 'Đúng lúc sắp / đang / vừa mới ...', 'Nhấn mạnh một thời điểm cụ thể của hành động. Tùy thuộc vào thì của động từ đi trước mà ý nghĩa khác nhau: Vるところ (chuẩn bị làm), Vているところ (đang làm dở), Vたところ (vừa mới làm xong).', 'Có thể đi kèm trợ từ (ところへ、ところで、ところを) tùy thuộc vào động từ ở vế sau.', '[{"japanese":"これからご飯を食べるところです。","hiragana":"これからごはんをたべるところです。","vietnamese":"Bây giờ chuẩn bị ăn cơm."},{"japanese":"今から出かけるところです。","hiragana":"いまからでかけるところです。","vietnamese":"Bây giờ tôi chuẩn bị đi ra ngoài."},{"japanese":"これから勉強するところです。","hiragana":"これからべんきょうするところです。","vietnamese":"Bây giờ chuẩn bị bắt đầu học."},{"japanese":"今からお風呂に入るところです。","hiragana":"いまからおふろにはいるところです。","vietnamese":"Bây giờ chuẩn bị đi tắm."},{"japanese":"これから映画が始まるところです。","hiragana":"これからえいががはじまるところです。","vietnamese":"Bây giờ bộ phim chuẩn bị bắt đầu."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3_L02_G001', 'SHINKANZEN_N3', 'L02', 'N3', '～とおりだ・～とおり（に）／～どおりだ・～どおり（に）', 'Vる・Vた + とおりに / N + の + とおりに / N + どおりに', 'Theo đúng như / Y như ...', 'Sử dụng khi muốn nói hành động ở vế sau được thực hiện giống hệt, tuân theo đúng nội dung, quy định, dự đoán hay chỉ dẫn ở vế trước.', 'Đây là cấu trúc thường gặp khi mô tả việc làm theo bản vẽ, sách hướng dẫn, hoặc việc xảy ra đúng như dự đoán.', '[{"japanese":"先輩に教えてもらったとおりに、パソコンを設定しました。","hiragana":"せんぱいにおしえてもらったとおりに、パソコンをせっていしました。","vietnamese":"Tôi đã cài đặt máy tính theo đúng như tiền bối đã chỉ dạy."},{"japanese":"説明書に書いてあるとおりに、組み立ててください。","hiragana":"せつめいしょにかいてあるとおりに、くみたててください。","vietnamese":"Xin hãy lắp ráp theo đúng như được viết trong sách hướng dẫn."},{"japanese":"今から私が言うとおりに、書いてください。","hiragana":"いまからわたしがいうとおりに、かいてください。","vietnamese":"Bây giờ xin hãy viết theo đúng như những gì tôi nói."},{"japanese":"予想したとおり、今日の試合は私たちのチームが勝ちました。","hiragana":"よそうしたとおり、きょうのしあいはわたしたちのチームがかちました。","vietnamese":"Đúng như dự đoán, trận đấu hôm nay đội của chúng tôi đã thắng."},{"japanese":"予定どおりに、会議は３時に終わりました。","hiragana":"よていどおりに、かいぎは３じにおわりました。","vietnamese":"Theo đúng kế hoạch, cuộc họp đã kết thúc lúc 3 giờ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3_L02_G002', 'SHINKANZEN_N3', 'L02', 'N3', '～によって・～によっては', 'N + によって / N + によっては', 'Tùy vào / Tùy theo ... mà khác nhau', 'Diễn tả ý nghĩa: tùy thuộc vào từng người, từng nơi, từng thời điểm hay từng trường hợp (A) mà kết quả, cách thức hoặc sự việc (B) sẽ khác nhau hoặc thay đổi theo.', 'Trong bài này chỉ tập trung vào ý nghĩa "Tùy theo sự khác biệt", không trộn với các nghĩa khác của によって như "Bởi ai đó" (câu bị động) hay "Do/Vì" (nguyên nhân).', '[{"japanese":"国によって、文化や習慣が違います。","hiragana":"くにによって、ぶんかやしゅうかんがちがいます。","vietnamese":"Tùy vào mỗi quốc gia mà văn hóa và phong tục sẽ khác nhau."},{"japanese":"人によって、考え方が異なります。","hiragana":"ひとによって、かんがえかたがことなります。","vietnamese":"Tùy vào mỗi người mà cách suy nghĩ sẽ khác biệt."},{"japanese":"季節によって、見える景色が変わります。","hiragana":"きせつによって、みえるけしきがかわります。","vietnamese":"Tùy vào mùa mà phong cảnh có thể nhìn thấy sẽ thay đổi."},{"japanese":"時代によって、流行する服が変わります。","hiragana":"じだいによって、りゅうこうするふくがかわります。","vietnamese":"Tùy vào từng thời đại mà quần áo thịnh hành sẽ thay đổi."},{"japanese":"天気によっては、明日のイベントは中止になるかもしれません。","hiragana":"てんきによっては、あしたのイベントはちゅうしになるかもしれません。","vietnamese":"Tùy thuộc vào thời tiết mà sự kiện ngày mai có thể bị hủy (đôi khi xảy ra)."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3_L02_G003', 'SHINKANZEN_N3', 'L02', 'N3', '～たびに', 'Vる + たびに / N + の + たびに', 'Mỗi khi / Cứ mỗi lần ...', 'Dùng khi muốn nói: "Cứ mỗi lần hành động A xảy ra, thì chắc chắn hành động/sự việc B cũng sẽ xảy ra theo". Nhấn mạnh tính lặp đi lặp lại một cách thường xuyên.', 'Thường đi kèm với những từ thể hiện cảm xúc, nhận xét, hoặc một hành động đặc trưng.', '[{"japanese":"この写真を見るたびに、学生時代を思い出します。","hiragana":"このしゃしんをみるたびに、がくせいじだいをおもいだします。","vietnamese":"Mỗi khi nhìn bức ảnh này, tôi lại nhớ về thời sinh viên."},{"japanese":"父は出張のたびに、お土産を買ってきてくれます。","hiragana":"ちちはしゅっちょうのたびに、おおみやげをかってきてくれます。","vietnamese":"Bố tôi cứ mỗi lần đi công tác lại mua quà lưu niệm về cho tôi."},{"japanese":"彼女は会うたびに、きれいになっていきます。","hiragana":"かのじょはあうたびに、きれいになっていきます。","vietnamese":"Cô ấy cứ mỗi lần gặp lại trở nên xinh đẹp hơn."},{"japanese":"辞書を引くたびに、新しい漢字を覚えます。","hiragana":"じしょをひくたびに、あたらしいかんじをおぼえます。","vietnamese":"Mỗi lần tra từ điển, tôi lại nhớ thêm được chữ Kanji mới."},{"japanese":"日本へ行くたびに、新しい友達ができます。","hiragana":"にほんへいくたびに、あたらしいともだちができます。","vietnamese":"Mỗi lần đi Nhật, tôi lại có thêm bạn mới."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3_L02_G004', 'SHINKANZEN_N3', 'L02', 'N3', '（～ば）～ほど・（～なら）～ほど・～ほど', 'Vば + Vる + ほど / Aければ + Aい + ほど / Naなら + Naな + ほど / N + ほど', 'Càng ... càng ...', 'Diễn tả ý nghĩa: Nếu mức độ của A tăng lên thì mức độ của B cũng tăng lên (hoặc giảm đi) tương ứng.', 'Chủ ngữ của cả 2 vế thường giống nhau. Động từ và tính từ phải được lặp lại.', '[{"japanese":"外国語は、勉強すればするほど難しくなります。","hiragana":"がいこくごは、べんきょうすればするほどむずかしくなります。","vietnamese":"Ngoại ngữ thì càng học càng trở nên khó."},{"japanese":"荷物は軽ければ軽いほど、旅行に便利です。","hiragana":"にもつはかるければかるいほど、りょこうにべんりです。","vietnamese":"Hành lý càng nhẹ thì càng tiện lợi cho chuyến du lịch."},{"japanese":"この本は、読めば読むほど面白くなります。","hiragana":"このほんは、よめばよむほどおもしろくなります。","vietnamese":"Quyển sách này càng đọc thì càng thấy thú vị."},{"japanese":"アパートは駅から近ければ近いほど、家賃が高くなります。","hiragana":"アパートはえきからちかければちかいほど、やちんがたかくなります。","vietnamese":"Căn hộ càng gần nhà ga thì tiền thuê nhà càng cao."},{"japanese":"パソコンの操作は、使えば使うほど慣れてきます。","hiragana":"パソコンのそうさは、つかえばつかうほどなれてきます。","vietnamese":"Thao tác máy tính thì càng dùng nhiều sẽ càng quen."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.grammar_rules (id, book_id, chapter_id, level, title, structure, meaning, explanation, notes, examples) values ('N3_L02_G005', 'SHINKANZEN_N3', 'L02', 'N3', '～ついでに', 'Vる・Vた + ついでに / N + の + ついでに', 'Nhân tiện / Tiện thể ...', 'Dùng khi muốn nói: "Nhân cơ hội đang làm việc chính (A), thì tranh thủ làm luôn việc phụ (B)".', 'Không dùng cho những sự việc tự nhiên xảy ra ngoài ý muốn.', '[{"japanese":"銀行へ行くついでに、郵便局にも寄りました。","hiragana":"ぎんこうへいくついでに、ゆうびんきょくにもよりました。","vietnamese":"Nhân tiện đi ngân hàng, tôi đã ghé qua cả bưu điện."},{"japanese":"スーパーへ買い物のついでに、本屋へ行きました。","hiragana":"スーパーへかいもののついでに、ほんやへいきました。","vietnamese":"Nhân tiện đi siêu thị mua sắm, tôi đã đến hiệu sách."},{"japanese":"散歩のついでに、コンビニでパンを買ってきました。","hiragana":"さんぽのついでに、コンビニでパンをかってきました。","vietnamese":"Nhân tiện đi dạo, tôi đã mua bánh mì ở cửa hàng tiện lợi."},{"japanese":"仕事で東京へ行ったついでに、友達に会いました。","hiragana":"しごとでとうきょうへいったついでに、ともだちにあいました。","vietnamese":"Nhân tiện đi Tokyo công tác, tôi đã gặp bạn bè."},{"japanese":"部屋の掃除をするついでに、窓も拭きました。","hiragana":"へやのそうじをするついでに、まどもふきました。","vietnamese":"Nhân tiện dọn dẹp phòng, tôi đã lau luôn cả cửa sổ."}]'::jsonb) on conflict (id) do update set book_id = excluded.book_id, chapter_id = excluded.chapter_id, level = excluded.level, title = excluded.title, structure = excluded.structure, meaning = excluded.meaning, explanation = excluded.explanation, notes = excluded.notes, examples = excluded.examples;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n5-1', 'kanji', 'N5', 'mcq', 'きょうは 【天気】 が いいですね。', null, '["てんき","でんき","げんき","てんぎ"]'::jsonb, 0, '天気 (てんき - Thiên khí): thời tiết. Lưu ý khác với でんき (電気 - điện) và げんき (元気 - khỏe mạnh).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n5-2', 'kanji', 'N5', 'mcq', 'まいにち 【電車】 で がっこうへ いきます。', null, '["てんしゃ","でんしゃ","でんちゃ","じんしゃ"]'::jsonb, 1, '電車 (でんしゃ - Điện xa): tàu điện. Âm On của 電 là でん, 車 là しゃ.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n5-3', 'kanji', 'N5', 'mcq', 'らいしゅうの 【きんようび】 に かいぎが あります。', null, '["木曜日","金曜日","土曜日","水曜日"]'::jsonb, 1, 'きんようび = 金曜日 (Thứ Sáu). 木曜日 là thứ Năm, 土曜日 là thứ Bảy, 水曜日 là thứ Tư.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n5-4', 'kanji', 'N5', 'mcq', 'あたらしい 【時計】 を かいました。', null, '["じけい","とけい","どけい","とき"]'::jsonb, 1, '時計 (とけい - Thời kế): đồng hồ. Đây là cách đọc đặc biệt cần nhớ (không đọc là じけい).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n5-5', 'kanji', 'N5', 'mcq', 'えきの 【みなみぐち】 で まって います。', null, '["北口","東口","西口","南口"]'::jsonb, 3, 'みなみぐち = 南口 (Cửa Nam). 北 (bắc - きた), 東 (đông - ひがし), 西 (tây - にし).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n4-1', 'kanji', 'N4', 'mcq', 'しゅくだいを 【計画】 どおりに すすめます。', null, '["けいかく","けいがく","きかく","けっかく"]'::jsonb, 0, '計画 (けいかく - Kế hoạch): kế hoạch. 画 trong trường hợp này đọc là かく.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n4-2', 'kanji', 'N4', 'mcq', 'へやの かぎを 【閉めて】 ください。', null, '["とめて","しめて","あけて","きめて"]'::jsonb, 1, '閉める (しめる - Bế): đóng lại. 開ける (あける) là mở, 止める (とめる) là dừng.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n4-3', 'kanji', 'N4', 'mcq', 'なつやすみの 【よてい】 を ともだちに はなしました。', null, '["予低","予定","余定","与定"]'::jsonb, 1, 'よてい = 予定 (Dự định): dự định, lịch trình.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n4-4', 'kanji', 'N4', 'mcq', 'ちかくの 【病院】 へ いきました。', null, '["びょういん","びよういん","びょうえん","ひょういん"]'::jsonb, 0, '病院 (びょういん - Bệnh viện). Chú ý phân biệt trường âm với 美容院 (びよういん - tiệm làm tóc).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n4-5', 'kanji', 'N4', 'mcq', 'かんじの 【いみ】 が わかりません。', null, '["意見","意味","異味","医見"]'::jsonb, 1, 'いみ = 意味 (Ý vị): ý nghĩa. 意見 (いけん) là ý kiến.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n3-1', 'kanji', 'N3', 'mcq', 'この問題については、もう一度【検討】する必要があります。', null, '["けんとう","けんどう","げんとう","かんとう"]'::jsonb, 0, '検討 (けんとう - Kiểm thảo): xem xét, cân nhắc kỹ lưỡng.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n3-2', 'kanji', 'N3', 'mcq', '友達の引っ越しを【手伝った】。', null, '["てつだった","てつたった","でんたつした","てつだいた"]'::jsonb, 0, '手伝う (てつだう - Thủ truyền): giúp đỡ. Thể quá khứ là 手伝った (てつだった).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-kanji-n3-3', 'kanji', 'N3', 'mcq', 'かいぎの しりょうを 【じゅんび】 しておいてください。', null, '["準備","順備","準美","純備"]'::jsonb, 0, 'じゅんび = 準備 (Chuẩn bị): chuẩn bị sẵn sàng.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
