insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-n5-1', 'star', 'N5', 'star', 'きのう ____ ____ ★ ____ 。', 'きのう スーパーで おいしい りんごを かいました。', '[{"id":"c0","text":"スーパーで","originalIndex":0},{"id":"c1","text":"おいしい","originalIndex":1},{"id":"c2","text":"りんごを","originalIndex":2},{"id":"c3","text":"かいました","originalIndex":3}]'::jsonb, 2, 'Trật tự tự nhiên: Thời gian (きのう) + Địa điểm + で (スーパーで) + Tính từ bổ nghĩa (おいしい) + Tân ngữ (りんごを) + Động từ (かいました). Vị trí ★ là りんごを.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-n5-2', 'star', 'N5', 'star', 'わたしの へやには ____ ____ ★ ____ 。', 'わたしの へやには 大きい つくえが 一つ あります。', '[{"id":"c0","text":"大きい","originalIndex":0},{"id":"c1","text":"つくえが","originalIndex":1},{"id":"c2","text":"一つ","originalIndex":2},{"id":"c3","text":"あります","originalIndex":3}]'::jsonb, 1, 'Cấu trúc tồn tại: Địa điểm + には + Tính từ (大きい) + Danh từ + が (つくえが) + Lượng từ (一つ) + あります. Vị trí ★ là つくえが.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-n5-3', 'star', 'N5', 'star', 'あした ____ ____ ★ ____ と おもいます。', 'あした ともだちと えいがを みに いこう と おもいます。', '[{"id":"c0","text":"ともだちと","originalIndex":0},{"id":"c1","text":"えいがを","originalIndex":1},{"id":"c2","text":"みに","originalIndex":2},{"id":"c3","text":"いこう","originalIndex":3}]'::jsonb, 2, 'Mục đích đi đâu làm gì: えいがを みに (đi xem) + Thể ý định いこう + と おもいます. Vị trí ★ là みに.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-n4-1', 'star', 'N4', 'star', '先生の ____ ____ ★ ____ 書きました。', '先生の おっしゃった とおりに ノートに メモを 書きました。', '[{"id":"c0","text":"おっしゃった","originalIndex":0},{"id":"c1","text":"とおりに","originalIndex":1},{"id":"c2","text":"ノートに","originalIndex":2},{"id":"c3","text":"メモを","originalIndex":3}]'::jsonb, 1, 'Cụm ～とおりに ("đúng theo...") nối sau động từ chia quá khứ おっしゃった → tiếp nối hành động ノートに メモを 書きました.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-n4-2', 'star', 'N4', 'star', '日本へ ____ ____ ★ ____ なりました。', '日本へ 来てから 日本語が 少しずつ 話せるように なりました。', '[{"id":"c0","text":"来てから","originalIndex":0},{"id":"c1","text":"日本語が","originalIndex":1},{"id":"c2","text":"少しずつ","originalIndex":2},{"id":"c3","text":"話せるように","originalIndex":3}]'::jsonb, 2, 'Trạng từ 少しずつ (từng chút một) đứng trước động từ khả năng 話せるように なりました.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-n4-3', 'star', 'N4', 'star', 'このボタンを ____ ____ ★ ____ わかります。', 'このボタンを 押して みれば 動くか どうか わかります。', '[{"id":"c0","text":"押して","originalIndex":0},{"id":"c1","text":"みれば","originalIndex":1},{"id":"c2","text":"動くか","originalIndex":2},{"id":"c3","text":"どうか","originalIndex":3}]'::jsonb, 2, 'Vてみる (thử làm) + ば → Điều kiện; đi với mẫu nghi vấn ～か どうか ("có ... hay không"). Vị trí ★ là 動くか.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
