insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-N3_L02_G003_S012-12345', 'star', 'N3', 'star', '友達 ____ ____ ★ ____ 。', '友達と話すたびに、元気をもらえます。', '[{"id":"chunk_0","text":"と話す","originalIndex":0},{"id":"chunk_1","text":"たびに","originalIndex":1},{"id":"chunk_2","text":"元気を","originalIndex":2},{"id":"chunk_3","text":"もらえます","originalIndex":3}]'::jsonb, 1, 'Câu gốc: 友達と話すたびに、元気をもらえます。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-N3_L02_G003_S019-12345', 'star', 'N3', 'star', '____ ____ ★ ____ 買いたくなります。', '季節が変わるたびに、服を買いたくなります。', '[{"id":"chunk_0","text":"季節が","originalIndex":0},{"id":"chunk_1","text":"変わる","originalIndex":1},{"id":"chunk_2","text":"たびに","originalIndex":2},{"id":"chunk_3","text":"服を","originalIndex":3}]'::jsonb, 2, 'Câu gốc: 季節が変わるたびに、服を買いたくなります。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-N3_L02_G004_S012-12345', 'star', 'N3', 'star', '____ ____ ★ ____ 上手です。', '忙しい人ほど、時間の使い方が上手です。', '[{"id":"chunk_0","text":"忙しい","originalIndex":0},{"id":"chunk_1","text":"人ほど","originalIndex":1},{"id":"chunk_2","text":"時間の","originalIndex":2},{"id":"chunk_3","text":"使い方が","originalIndex":3}]'::jsonb, 1, 'Câu gốc: 忙しい人ほど、時間の使い方が上手です。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-N3_L02_G004_S019-12345', 'star', 'N3', 'star', '____ ____ ★ ____ 高い傾向があります。', '薬は新しければ新しいほど、値段が高い傾向があります。', '[{"id":"chunk_0","text":"薬","originalIndex":0},{"id":"chunk_1","text":"は","originalIndex":1},{"id":"chunk_2","text":"新しければ新しいほど","originalIndex":2},{"id":"chunk_3","text":"値段が","originalIndex":3}]'::jsonb, 2, 'Câu gốc: 薬は新しければ新しいほど、値段が高い傾向があります。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-N3_L02_G005_S012-12345', 'star', 'N3', 'star', '病院へ ____ ____ ★ ____ 。', '病院へお見舞いに行くついでに、花を買いました。', '[{"id":"chunk_0","text":"お見舞いに","originalIndex":0},{"id":"chunk_1","text":"行くついでに","originalIndex":1},{"id":"chunk_2","text":"花を","originalIndex":2},{"id":"chunk_3","text":"買いました","originalIndex":3}]'::jsonb, 1, 'Câu gốc: 病院へお見舞いに行くついでに、花を買いました。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-star-N3_L02_G005_S019-12345', 'star', 'N3', 'star', '犬の散歩 ____ ____ ★ ____ 。', '犬の散歩のついでに、公園を一周しました。', '[{"id":"chunk_0","text":"のついでに","originalIndex":0},{"id":"chunk_1","text":"公園","originalIndex":1},{"id":"chunk_2","text":"を","originalIndex":2},{"id":"chunk_3","text":"一周しました","originalIndex":3}]'::jsonb, 0, 'Câu gốc: 犬の散歩のついでに、公園を一周しました。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rs-n5-1_jlpt-rs-n5-1-q1', 'reading-short', 'N5', 'reading', '15日は どうして お休みですか。', 'Bảng thông báo của cửa hàng sách', '["店の 人が 休みたいからです。","電気の 工事が あるからです。","本が ぜんぶ 売れたからです。","木曜日の じゅんびが あるからです。"]'::jsonb, 1, 'Đoạn văn ghi rõ: 「店内の電気の工事のため、お休みします。」 (Nghỉ do sửa chữa điện trong cửa hàng).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rs-n5-1_jlpt-rs-n5-1-q2', 'reading-short', 'N5', 'reading', '16日の 午前10時半に 本を 買いに 行きます。店は どうですか。', 'Bảng thông báo của cửa hàng sách', '["開いて います。","まだ 開いて いません。","休みです。","午後から 開きます。"]'::jsonb, 0, 'Từ thứ Năm ngày 16 mở cửa từ 10:00 sáng đến 9:00 tối nên 10:30 sáng cửa hàng đang mở.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rs-n4-1_jlpt-rs-n4-1-q1', 'reading-short', 'N4', 'reading', 'このメールを書いた人は、山田さんに何をお願いしていますか。', 'Email hẹn gặp cuối tuần', '["大阪へいっしょに来てほしい。","映画を見に行く日を日曜日に変えてほしい。","土曜日の夜に駅まで迎えに来てほしい。","映画のチケットを一人で見てきてほしい。"]'::jsonb, 1, 'Người viết hỏi cuối email: 「日曜日に変更してもいいですか。」 (Đổi sang Chủ nhật được không?).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rs-n3-1_jlpt-rs-n3-1-q1', 'reading-short', 'N3', 'reading', '会議について正しいものはどれですか。', 'Thông báo đổi phòng họp công ty', '["開始時間が午後2時から変更になった。","資料は各自で印刷して持っていかなければならない。","参加人数が増えたので、より広い部屋に変更された。","3階の会議室Aで行われることになった。"]'::jsonb, 2, 'Vì số người tham gia tăng (参加者が増えたため) nên chuyển sang phòng họp lớn (大会議室) ở tầng 5.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n5-1_jlpt-rm-n5-1-q1', 'reading-medium', 'N5', 'reading', '家族は どうやって デパートへ 行きましたか。', 'Cuối tuần đi mua sắm cùng gia đình', '["バスで 行きました。","電車で 行きました。","歩いて 行きました。","車で 行きました。"]'::jsonb, 2, 'Lúc đi gia đình chọn đi bộ vì thời tiết đẹp (バスではなく、歩いて行きました). Lúc về mới đi tàu điện.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n5-1_jlpt-rm-n5-1-q2', 'reading-medium', 'N5', 'reading', 'どうして 電車で 家へ 帰りましたか。', 'Cuối tuần đi mua sắm cùng gia đình', '["天気が わるくなったからです。","買い物を して 荷物が 重かったからです。","午後 4時に なって 急いでいたからです。","バスが なかったからです。"]'::jsonb, 1, 'Sau khi mua áo, bánh kẹo và hoa quả, hành lý nặng (荷物が重かった) nên cả nhà đi tàu về.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n4-1_jlpt-rm-n4-1-q1', 'reading-medium', 'N4', 'reading', '筆者は どうして 紙の本を 読むようになりましたか。', 'Thói quen đọc sách trên tàu điện', '["スマートフォンの料金が高くなったから。","スマホを見ていると目が疲れやすくなったから。","電車の中でゲームが禁止されたから。","小説のほうがニュースより速く読めるから。"]'::jsonb, 1, 'Tác giả nêu rõ lý do: 「目が疲れやすくなりました。そこで、先月から小さめの小説を持ち歩くようにしました。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n4-1_jlpt-rm-n4-1-q2', 'reading-medium', 'N4', 'reading', '筆者が選んでいる本は どんな本ですか。', 'Thói quen đọc sách trên tàu điện', '["写真がたくさん入った大きい本","片手で持てるサイズの小さい小説","仕事に関係する専門書","毎朝駅で配られるニュースの本"]'::jsonb, 1, '「小さめの小説」 và 「片手で持てるサイズなので、立っているときでも楽に読めます。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n3-1_jlpt-rm-n3-1-q1', 'reading-medium', 'N3', 'reading', 'テレワークの課題として挙げられているのはどれですか。', 'Làm việc từ xa và ranh giới nghỉ ngơi', '["通勤時間が長くなってストレスが増えること。","自分のペースで仕事をすることがまったくできないこと。","仕事と休みの時間の境界が曖昧になりやすいこと。","会社のパソコンが自宅で使えないこと。"]'::jsonb, 2, 'Vấn đề được nêu ở đoạn 2 là khó phân biệt công việc và đời tư (仕事とプライベートの区別がつきにくい).', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rm-n3-1_jlpt-rm-n3-1-q2', 'reading-medium', 'N3', 'reading', '筆者はテレワークをうまく続けるために何が必要だと述べていますか。', 'Làm việc từ xa và ranh giới nghỉ ngơi', '["毎日必ず会社に一度顔を出すこと","場所や時間を意識的に分けて気分を切り替えること","夜遅くまで働いて昼間に長く寝ること","パソコンを使わずに紙だけで仕事すること"]'::jsonb, 1, 'Đoạn cuối đề xuất tách nơi làm/nghỉ hoặc đi dạo theo giờ để chủ động phân tách công việc và nghỉ ngơi.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n3-1_jlpt-rl-n3-1-q1', 'reading-long', 'N3', 'reading', '便利で速い社会になって、どんな問題が起きていると筆者は言っていますか。', 'Giá trị của việc "chờ đợi" trong thời đại tốc độ', '["インターネットの注文で荷物が届かないことが増えた。","少し待つだけでイライラしたり怒ったりする人が増えた。","電車の本数が減って乗り換えに時間がかかるようになった。","手紙を書く人が増えたが返事が遅くなっている。"]'::jsonb, 1, 'Đoạn 2 nêu rõ: vì quá quen tốc độ nên người dễ cáu kỉnh khi phải chờ dù chỉ 3 phút.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n3-1_jlpt-rl-n3-1-q2', 'reading-long', 'N3', 'reading', '筆者が手紙や料理の例を出したのはなぜですか。', 'Giá trị của việc "chờ đợi" trong thời đại tốc độ', '["手紙や料理はできるだけ速く仕上げるべきだと伝えるため。","レストランのサービスが悪い理由を説明するため。","待つ時間にも楽しみや価値があることを示すため。","メールより手紙のほうが仕事で役に立つと言うため。"]'::jsonb, 2, 'Đoạn 3 dùng ví dụ thư tay và món ăn để minh họa vai trò & giá trị của thời gian chờ đợi.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n3-1_jlpt-rl-n3-1-q3', 'reading-long', 'N3', 'reading', '筆者の考えに最も合っているものはどれですか。', 'Giá trị của việc "chờ đợi" trong thời đại tốc độ', '["どんな場面でもスピードよりゆっくりすることが大切だ。","日常の待ち時間はすべて無駄なので減らすべきだ。","緊急時以外は、待つ時間も味わいながら過ごすとよい。","レストランでは料理が出てくるまでスマホを見るべきだ。"]'::jsonb, 2, 'Đoạn kết: trong công việc/khẩn cấp cần tốc độ, nhưng với khoảng chờ nhỏ hằng ngày thì nên thư giãn đón nhận thay vì coi là lãng phí.', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n4-1_jlpt-rl-n4-1-q1', 'reading-long', 'N4', 'reading', 'わたしは どうして すぐに りょうりを 始められませんでしたか。', 'Kinh nghiệm học nấu ăn ở câu lạc bộ trường', '["包丁を持っていなかったから。","アルバイトが いそがしかったから。","りょうりクラブが 木曜日にしかなかったから。","せんぱいが こわかったから。"]'::jsonb, 1, 'Đoạn 1: 「でも、アルバイトがいそがしくて、なかなか始めることができませんでした。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n4-1_jlpt-rl-n4-1-q2', 'reading-long', 'N4', 'reading', 'このクラブについて正しいものはどれですか。', 'Kinh nghiệm học nấu ăn ở câu lạc bộ trường', '["毎週日本の伝統りょうりだけを作る。","留学生もいっしょに参加している。","毎週日曜日の朝に集まっている。","今でも家ではまったく作れない。"]'::jsonb, 1, 'Đoạn 2: 「日本人の学生だけでなく、留学生もたくさん参加しています。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n5-1_jlpt-rl-n5-1-q1', 'reading-long', 'N5', 'reading', 'わたしは 平日の 午後、よく 何を していますか。', 'Bức thư gửi thầy giáo cũ', '["アルバイトを しています。","図書館で 宿題をしたり 友達と話したり しています。","浅草へ お寺を 見に 行っています。","日本語の クラスで 授業を 受けています。"]'::jsonb, 1, 'Thư viết: 「午後は図書館で宿題をしたり、友達と話したりしています。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-rl-n5-1_jlpt-rl-n5-1-q2', 'reading-long', 'N5', 'reading', '先週の 日曜日は だれと どこへ 行きましたか。', 'Bức thư gửi thầy giáo cũ', '["木村先生と 公園へ 行きました。","クラスの 友達と 浅草へ 行きました。","ひとりで 東京駅へ 行きました。","家族と 図書館へ 行きました。"]'::jsonb, 1, '「同じクラスのベトナム人の友達と浅草へ行きました。」', null) on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n5-1', 'listening', 'N5', 'listening', null, null, '["漢字のプリント","作文（さくぶん）","テストの紙","教科書"]'::jsonb, 0, 'Giáo viên nói rõ: bài tập ngày mai là 漢字のプリント, còn 作文 để sang thứ Hai tuần sau.', 'みなさん、あしたの しゅくだいは かんじの プリントです。さくぶんは 来週の 月曜日で いいですよ。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n5-2', 'listening', 'N5', 'listening', null, null, '["お疲れさまでした。","いらっしゃいませ。","いただきます。","こちらこそ、お願いします。"]'::jsonb, 0, 'Khi ai đó chào về trước (お先に失礼します), câu đáp lịch sự chuẩn tiếng Nhật là 「お疲れさまでした。」', 'きょうは これで おわります。お先に 失礼します。') on conflict (id) do update set module_id = excluded.module_id, level = excluded.level, question_type = excluded.question_type, prompt = excluded.prompt, passage = excluded.passage, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, audio_text = excluded.audio_text;
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n4-1', 'listening', 'N4', 'listening', null, null, '["コーヒーが とても 安いから","駅に いちばん 近くて にぎやかだから","Wi-Fiがあって 静かで 勉強しやすいから","ケーキが 無料（むりょう）だから"]'::jsonb, 2, 'Bạn nữ phủ nhận chuyện giá rẻ (ねだんは ふつう) và nêu lý do có Wi-Fi và yên tĩnh (静かなんだ) để học bài.', '駅前に 新しいカフェが できたね。あそこ、コーヒーが 安いの？
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n4-2', 'listening', 'N4', 'listening', null, null, '["入口のすぐ左側","突き当たりの野菜コーナーを右に曲がった所","野菜コーナーを左に曲がった所","2階のエスカレーターの前"]'::jsonb, 1, 'Nhân viên chỉ dẫn đi thẳng tới cuối đường (突き当たりの野菜コーナー) rồi rẽ phải (右に曲がったところ).', 'すみません、パンの 売り場は どちらですか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n3-1', 'listening', 'N3', 'listening', null, null, '["数字やグラフの ページを もっと 増やす","細かい データを すべて 削除して 作り直す","1ページの情報量を減らして 読みやすく整理する","文字を さらに 小さくして 1枚に まとめる"]'::jsonb, 2, 'Anh đồng nghiệp khuyên dữ liệu đã đủ (十分そろっている), cần giảm lượng thông tin mỗi trang cho thoáng (情報量を減らしてすっきりさせる).', '来週のプレゼン資料、数字やグラフを もっと 増やした ほうが いいでしょうか。
insert into public.jlpt_questions (id, module_id, level, question_type, prompt, passage, options, correct_index, explanation, audio_text) values ('jlpt-lis-n3-2', 'listening', 'N3', 'listening', null, null, '["はい、すぐに取りに戻ってまいります。","いいえ、机の上に置いたままにしてください。","はい、部長が取りに行ってくださいますか。","すみません、そのまま会議を始めますか。"]'::jsonb, 0, '「取りに戻ってまいります」 sử dụng khiêm nhường ngữ (まいります) phù hợp khi báo với cấp trên là mình sẽ lập tức quay lại lấy.', 'すみません、部長。会議で 使う 資料を 机の上に 置いてきて しまいました。
